const request = $('接收产品链接').first().json.body || {};
const html = String($input.first().json.page_html || '');
const url = String(request.product_url || '').trim();
if (!/^https?:\/\//i.test(url)) {
  return [{ json: { ok: false, error: '请输入有效的 http/https 商品链接' } }];
}
const decode = (value) => String(value || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();
const match = (pattern) => decode((html.match(pattern) || [])[1] || '');
let productName = match(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)/i)
  || match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const description = match(/<meta[^>]+(?:name|property)=["'](?:description|og:description)["'][^>]+content=["']([^"']+)/i);
if (!productName) {
  const parsed = new URL(url);
  productName = decodeURIComponent(parsed.pathname.split('/').filter(Boolean).pop() || parsed.hostname)
    .replace(/[-_]+/g, ' ');
}
productName = productName.slice(0, 80) || '未命名产品';
const sourceText = (description || productName).slice(0, 240);
const sellingPoints = [
  sourceText || '商品核心价值清晰',
  '适合通过真实体验建立信任',
  '可用短视频快速说明使用场景'
];
const brief = {
  product_name: productName,
  category: '电商商品',
  target_audience: '关注实用价值、使用体验与购买决策效率的消费者',
  core_selling_points: sellingPoints,
  pain_points: '用户需要快速判断产品是否适合自己，并降低购买前的信息不确定性',
  source_url: url,
  source_description: description
};
const specs = [
  ['反常识开场', '认知阶段', '惊讶', '先打破用户对价格或效果的固有判断'],
  ['痛点共鸣', '问题阶段', '共鸣', '从真实使用困扰切入'],
  ['结果前置', '解决方案阶段', '期待', '先展示使用后的直观变化'],
  ['价格锚点', '购买阶段', '省心', '用成本对比降低决策门槛'],
  ['场景代入', '问题阶段', '真实', '把产品放进高频生活场景'],
  ['体验反转', '认知阶段', '好奇', '用前后态度变化制造反差'],
  ['细节证据', '产品阶段', '信任', '用可验证细节支撑卖点'],
  ['避坑建议', '解决方案阶段', '安全感', '从选购误区建立专业感'],
  ['限时行动', '购买阶段', '紧迫', '用明确行动理由推动转化'],
  ['朋友推荐', '产品阶段', '亲近', '用自然口吻降低广告感'],
  ['挑战测试', '解决方案阶段', '好奇', '通过测试过程证明产品表现'],
  ['一句话结论', '购买阶段', '确定', '用清晰结论帮助用户快速决策']
];
const hooks = specs.map((item, index) => ({
  hook_id: 'hook_' + String(index + 1).padStart(2, '0'),
  title: index === 0 ? productName + '真的值得买吗？' : item[0] + '：' + productName,
  score: 10 - (index % 3),
  category: item[0],
  awareness_stage: item[1],
  emotion: item[2],
  description: item[3] + '。' + (description || sellingPoints[0])
}));
return [{ json: {
  ok: true,
  product_record_id: 'product_' + Date.now(),
  product_brief: brief,
  hooks
} }];
